/* From Uiverse.io by Pradeepsaranbishnoi - Tags: loader */
.__UIV_SCOPE__ .preloader {
  position: absolute;
  margin-left: -55px;
  margin-top: -100px;
  height: 110px;
  width: 110px;
  left: 50%;
  top: 50%;
}

.__UIV_SCOPE__ svg {
  width: 110px;
  height: 110px;
}

.__UIV_SCOPE__ path {
  stroke: #9ea1a4;
  stroke-width: 0.25;
  fill: #241E20;
}

.__UIV_SCOPE__ #cloud {
  position: relative;
  z-index: 2;
}

.__UIV_SCOPE__ #cloud path {
  fill: #efefef;
}

.__UIV_SCOPE__ #sun {
  margin-left: -10px;
  margin-top: 6px;
  opacity: 0;
  width: 60px;
  height: 60px;
  position: absolute;
  left: 45px;
  top: 15px;
  z-index: 1;
  animation-name: rotate;
  animation-duration: 16000ms;
  animation-iteration-count: infinite;
  animation-timing-function: linear;
}

.__UIV_SCOPE__ #sun path {
  stroke-width: 0.18;
  fill: #9ea1a4;
}

@keyframes rotate {
  0% {
    transform: rotateZ(0deg);
  }

  100% {
    transform: rotateZ(360deg);
  }
}

/* Rain */
.__UIV_SCOPE__ .rain {
  position: absolute;
  width: 70px;
  height: 70px;
  margin-top: -32px;
  margin-left: 19px;
}

.__UIV_SCOPE__ .drop {
  opacity: 1;
  background: #9ea1a4;
  display: block;
  float: left;
  width: 3px;
  height: 10px;
  margin-left: 4px;
  border-radius: 0px 0px 6px 6px;
  animation-name: drop;
  animation-duration: 350ms;
  animation-iteration-count: infinite;
}

.__UIV_SCOPE__ .drop:nth-child(1) {
  animation-delay: -130ms;
}

.__UIV_SCOPE__ .drop:nth-child(2) {
  animation-delay: -240ms;
}

.__UIV_SCOPE__ .drop:nth-child(3) {
  animation-delay: -390ms;
}

.__UIV_SCOPE__ .drop:nth-child(4) {
  animation-delay: -525ms;
}

.__UIV_SCOPE__ .drop:nth-child(5) {
  animation-delay: -640ms;
}

.__UIV_SCOPE__ .drop:nth-child(6) {
  animation-delay: -790ms;
}

.__UIV_SCOPE__ .drop:nth-child(7) {
  animation-delay: -900ms;
}

.__UIV_SCOPE__ .drop:nth-child(8) {
  animation-delay: -1050ms;
}

.__UIV_SCOPE__ .drop:nth-child(9) {
  animation-delay: -1130ms;
}

.__UIV_SCOPE__ .drop:nth-child(10) {
  animation-delay: -1300ms;
}

@keyframes drop {
  50% {
    height: 45px;
    opacity: 0;
  }

  51% {
    opacity: 0;
  }

  100% {
    height: 1px;
    opacity: 0;
  }
}

.__UIV_SCOPE__ .text {
  font-family: Helvetica, 'Helvetica Neue', sans-serif;
  letter-spacing: 1px;
  text-align: center;
  margin-left: -43px;
  font-weight: bold;
  margin-top: 20px;
  font-size: 11px;
  color: #a0a0a0;
  width: 200px;
}
